import {content,interests} from './content.js';
import {esc,download,questionResult,countAnswers,normalizeAnswers} from './core.js';
import {configured,login,logout,rpc} from './api.js';
import {gestures,observationLabels,summarize,exportParticipants,exportSummary,stages,progressCounts} from './reporting.js';
import {installComfort} from './comfort.js';
installComfort();
const root=document.querySelector('main');
let sessions=[],selected=null,participants=[],demo=false,poll,detail=null,tab='participants',query='',filter='all',observationDirty=false;
function message(e){const n=document.querySelector('#error');if(n){n.textContent=e.message||e;n.className='error';}}
function signIn(){
 clearInterval(poll);detail=null;const active=configured();
 root.innerHTML=`<div class="narrow"><p class="eyebrow">Espace animateur</p><h1>Observer les acquis, préparer la suite</h1><p class="lead">Un suivi par participant et une synthèse par domaine pour orienter les ateliers.</p><form class="card" id="login"><h2>${active?'Connexion':'Explorer le tableau de bord'}</h2>${!active?'<div class="notice">La démonstration contient uniquement des données fictives. La collecte réelle n’est pas encore activée.</div>':'<label for="email">Adresse e-mail</label><input id="email" type="email" autocomplete="username" required><label for="password">Mot de passe</label><input id="password" type="password" autocomplete="current-password" required>'}<p id="error" role="alert"></p><div class="actions">${active?'<button>Se connecter</button>':''}<button type="button" class="${active?'secondary':''}" id="demo">Voir une séance fictive</button></div></form></div>`;
 document.querySelector('#login').onsubmit=async e=>{
  e.preventDefault();if(!active)return;const b=e.submitter;b.disabled=true;
  try{await login(document.querySelector('#email').value,document.querySelector('#password').value);await rpc('trainer_check',{},true);demo=false;await loadSessions();}
  catch(err){message(err);b.disabled=false;}
 };
 document.querySelector('#demo').onclick=()=>{
  demo=true;tab='participants';query='';filter='all';sessions=[{id:'demo',title:'Découverte du numérique',code:'DEMO2026',is_open:true}];selected=sessions[0];
  const all=Object.fromEntries(content.questions.map(q=>[q.id,q.answer]));
  participants=[
   {id:'fictif-1',name:'Camille (fictif)',answers:{Q1:'B',Q2:'NSP',Q3:'A',D1:'Réalisé seul',D2:'Réalisé avec aide',interests:['Fichiers et photos','E-mails et pièces jointes'],computer_ease:'Peu à l’aise',goal:'Envoyer mes documents sans aide.'},observations:{D1_open:'3',D1_window:'2',D2_text:'2'},finished:false,updated_at:new Date().toISOString()},
   {id:'fictif-2',name:'Alex (fictif)',answers:{...all,D1:'Réalisé seul',D2:'Réalisé seul',D3:'Réalisé avec aide',D4:'Réalisé seul',D5:'Réalisé seul',D6:'Réalisé avec aide',interests:['Sécurité des comptes','Fichiers et photos'],goal:'Retrouver mes documents.',S1:'Je ne clique pas. Je contacte le service par son site officiel.'},observations:Object.fromEntries(gestures.map(g=>[g.id,['D3_save','D6_file'].includes(g.id)?'2':'3'])),finished:true,updated_at:new Date().toISOString()},
   {id:'fictif-3',name:'Sam (fictif)',answers:{...all,Q3:'NSP',Q4:'B',Q7:'NSP',D1:'Réalisé avec aide',D2:'Réalisé seul',D3:'Essayé sans terminer',interests:['Fichiers et photos','E-mails et pièces jointes','Démarches et formulaires'],mobile_ease:'Très à l’aise',goal:'Faire une démarche depuis un ordinateur.'},observations:{D1_open:'2',D1_window:'1',D2_text:'3',D3_folder:'1',D3_save:'0',D3_find:'NO'},finished:false,updated_at:new Date().toISOString()}
  ];dashboard();
 };
}
async function loadSessions(){
 sessions=await rpc('trainer_sessions',{},true);selected=sessions.find(s=>s.id===selected?.id)||sessions[0]||null;
 await loadParticipants();dashboard();clearInterval(poll);
 poll=setInterval(async()=>{
  if(detail||!selected||document.activeElement?.closest('#results'))return;
  try{await loadParticipants();if(!detail){renderResults();const n=document.querySelector('#freshness');if(n)n.textContent='Actualisé à '+new Date().toLocaleTimeString('fr-FR');}}catch(e){message(e);}
 },15000);
}
async function loadParticipants(){
 const id=selected?.id;if(!id){participants=[];return;}
 const response=await rpc('trainer_participants',{p_session:id},true);
 if(selected?.id===id&&!demo)participants=response.map(p=>({...p,answers:normalizeAnswers(p.answers)}));
}
function dashboard(){
 detail=null;observationDirty=false;
 root.innerHTML=`<div class="split"><div><p class="eyebrow">${demo?'Démonstration · données fictives':'Espace animateur'}</p><h1>${selected?esc(selected.title):'Vos séances'}</h1></div><button id="logout" class="secondary">${demo?'Quitter la démonstration':'Se déconnecter'}</button></div><p id="error" role="alert"></p><div class="card session-card"><div class="form-row"><div><label for="session">Séance à consulter</label><select id="session">${sessions.length?sessions.map(s=>`<option value="${esc(s.id)}" ${s.id===selected?.id?'selected':''}>${esc(s.title)}${s.is_open?'':' · fermée'}</option>`).join(''):'<option>Aucune séance</option>'}</select></div><div>${selected?`<p class="muted">${demo?'Code fictif':'Code à donner au groupe'}</p><div class="split"><strong class="code">${esc(selected.code)}</strong><button id="copy-code" class="secondary small">Copier le code</button></div>`:''}</div></div><div class="actions">${selected?`<button id="refresh" class="secondary small">Actualiser</button><button id="toggle" class="secondary small" ${demo?'disabled':''}>${selected.is_open?'Fermer la collecte':'Rouvrir la collecte'}</button><span class="pill">${selected.is_open?'Collecte ouverte':'Collecte fermée'}</span>`:''}<span id="copy-status" class="status" role="status"></span></div><details><summary>Créer une nouvelle séance</summary><form id="create"><label for="title">Nom de la séance</label><div class="actions"><input id="title" maxlength="100" placeholder="Ex. Groupe du mardi" required><button ${demo?'disabled':''}>Créer</button></div>${demo?'<p class="muted">La création de séances sera disponible après connexion du service de collecte.</p>':''}</form></details></div><div class="tabs" role="tablist" aria-label="Vues de la séance">${[['participants','Participants'],['summary','Synthèse pédagogique'],['prepare','Préparer la séance']].map(([id,label])=>`<button role="tab" id="tab-${id}" data-tab="${id}" aria-selected="${tab===id}" aria-controls="results" tabindex="${tab===id?'0':'-1'}">${label}</button>`).join('')}</div><section id="results" role="tabpanel" aria-labelledby="tab-${tab}"></section>`;
 document.querySelector('#logout').onclick=async()=>{if(!demo)await logout().catch(()=>{});demo=false;selected=null;participants=[];signIn();};
 document.querySelector('#create').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{selected=await rpc('create_session',{p_title:document.querySelector('#title').value.trim()},true);await loadSessions();}catch(err){message(err);e.submitter.disabled=false;}};
 document.querySelector('#session').onchange=async e=>{selected=sessions.find(s=>s.id===e.target.value);query='';filter='all';try{if(!demo)await loadParticipants();dashboard();}catch(err){message(err);}};
 document.querySelector('#copy-code')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(selected.code);document.querySelector('#copy-status').textContent='Code copié.';}catch{document.querySelector('#copy-status').textContent='Sélectionnez le code pour le copier.';}});
 document.querySelector('#toggle')?.addEventListener('click',async()=>{if(selected.is_open&&!confirm('Fermer la collecte ? Les réponses encore sur les postes ne pourront plus être transmises avant réouverture.'))return;try{await rpc('set_session_open',{p_session:selected.id,p_open:!selected.is_open},true);await loadSessions();}catch(e){message(e);}});
 document.querySelector('#refresh')?.addEventListener('click',async()=>{try{if(!demo)await loadParticipants();renderResults();}catch(e){message(e);}});
 const tabs=[...document.querySelectorAll('[data-tab]')];
 tabs.forEach((b,i)=>{b.onclick=()=>{tab=b.dataset.tab;tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1;});renderResults();};b.onkeydown=e=>{const delta=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0;if(delta){e.preventDefault();const next=tabs[(i+delta+tabs.length)%tabs.length];next.click();next.focus();}};});
 renderResults();
}
function renderResults(){
 const box=document.querySelector('#results');if(!box)return;box.setAttribute('aria-labelledby','tab-'+tab);
 if(tab==='prepare'){prepareScreen(box);return;}
 if(!selected){box.innerHTML='<div class="card"><h2>Votre première séance</h2><p>Créez une séance pour obtenir un code et accueillir les participants.</p></div>';return;}
 if(tab==='summary'){summaryScreen(box);return;}
 box.innerHTML=`<div class="metrics"><div class="metric"><span>Participants</span><strong>${participants.length}</strong></div><div class="metric"><span>Parcours terminés</span><strong>${participants.filter(p=>p.finished).length}</strong></div><div class="metric"><span>Observations à compléter</span><strong>${participants.filter(p=>gestures.some(g=>!['0','1','2','3'].includes(p.observations?.[g.id]))).length}</strong></div></div><div class="card"><div class="split"><h2>Suivi des participants</h2><div class="actions"><button class="small" id="csv">Exporter tous les résultats</button><button class="small secondary" id="json">Sauvegarde JSON</button></div></div><p class="muted" id="freshness">${demo?'Exemple de séance.':'Actualisation automatique toutes les 15 secondes.'}</p><div class="form-row"><div><label for="search">Rechercher un prénom</label><input id="search" type="search" value="${esc(query)}" autocomplete="off"></div><div><label for="filter">Afficher</label><select id="filter">${[['all','Tout le groupe'],['progress','Parcours en cours'],['finished','Parcours terminés'],['observe','Observations à compléter']].map(([v,t])=>`<option value="${v}" ${filter===v?'selected':''}>${t}</option>`).join('')}</select></div></div><div id="participant-table"></div><p class="muted">Les compteurs décrivent les réponses reçues, sans noter la réussite. Les exports incluent tout le groupe, même si un filtre est actif.</p></div>`;
 document.querySelector('#csv').onclick=()=>download('diagnostic-'+selected.code+'.csv',exportParticipants(selected,participants),'text/csv;charset=utf-8');
 document.querySelector('#json').onclick=()=>download('seance-'+selected.code+'.json',JSON.stringify({session:selected,participants},null,2),'application/json');
 document.querySelector('#search').oninput=e=>{query=e.target.value;renderTable();};document.querySelector('#filter').onchange=e=>{filter=e.target.value;renderTable();};renderTable();
}
function renderTable(){
 const term=query.trim().toLocaleLowerCase('fr-FR');
 const shown=participants.filter(p=>p.name.toLocaleLowerCase('fr-FR').includes(term)&&(filter==='all'||filter==='progress'&&!p.finished||filter==='finished'&&p.finished||filter==='observe'&&gestures.some(g=>!['0','1','2','3'].includes(p.observations?.[g.id]))));
 document.querySelector('#participant-table').innerHTML=shown.length?`<p class="number">${shown.length} participant${shown.length>1?'s':''} affiché${shown.length>1?'s':''}</p><div class="scroll"><table><caption class="sr-only">Réponses et progression des participants</caption><thead><tr><th scope="col">Participant</th><th scope="col">Questions</th><th scope="col">Défis</th><th scope="col">Situations</th><th scope="col">Parcours</th><th scope="col">Détail</th></tr></thead><tbody>${shown.map(p=>{const n=progressCounts(p.answers);return `<tr><th scope="row">${esc(p.name)}<small class="muted row-meta">Reçu à ${new Date(p.updated_at).toLocaleTimeString('fr-FR')}</small></th><td>${n.questions}/12</td><td>${n.challenges}/6</td><td>${n.situations}/3</td><td><span class="pill">${p.finished?'Terminé':'En cours'}</span></td><td><button class="small secondary" data-id="${esc(p.id)}" aria-label="Ouvrir le dossier de ${esc(p.name)}">Ouvrir</button></td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty-state"><h3>${participants.length?'Aucun participant ne correspond':'En attente du groupe'}</h3><p>${participants.length?'Modifiez le prénom ou le filtre.':'Les participants apparaîtront après avoir rejoint la séance avec le code.'}</p></div>`;
 document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>participant(b.dataset.id));
}
function summaryScreen(box){
 const ds=summarize(participants);const demands=interests.map(t=>[t,participants.filter(p=>p.answers.interests?.includes(t)).length]).filter(x=>x[1]).sort((a,b)=>b[1]-a[1]);
 box.innerHTML=`<div class="card"><div class="split"><h2>Autonomie observée et besoins</h2><button id="summary-csv" class="small">Exporter cette synthèse</button></div><p>Chaque colonne compte des personnes. Une même personne peut apparaître dans plusieurs domaines.</p><div class="scroll"><table><caption class="sr-only">Synthèse du groupe par domaine</caption><thead><tr><th scope="col">Domaine</th><th scope="col">Sans aide</th><th scope="col">Avec aide</th><th scope="col">À observer</th><th scope="col">Connaissances à consolider</th><th scope="col">Sujet demandé</th></tr></thead><tbody>${ds.map(d=>`<tr><th scope="row">${d.label}</th>${d.challenges.length?`<td>${d.alone}</td><td>${d.help}</td><td>${d.unobserved}</td>`:'<td colspan="3" class="muted">Non évalué en pratique</td>'}<td>${d.knowledge}<small class="row-meta muted">${d.incomplete} avec réponse(s) manquante(s)</small></td><td>${d.requested}</td></tr>`).join('')}</tbody></table></div><details><summary>Comment lire ces résultats</summary><p>« Sans aide » : tous les gestes du domaine sont observés au code 3. « Avec aide » : au moins un geste est au code 0, 1 ou 2. « À observer » : aucun besoin d’aide relevé, mais au moins un geste manque. Une autoévaluation ne remplace pas l’observation.</p><p>« Connaissances à consolider » : au moins une erreur ou un « Je ne sais pas » parmi les questions du domaine. Les questions non répondues restent à part. Cette courte exploration ne certifie pas la maîtrise d’un domaine.</p></details></div><div class="card"><h2>Les envies du groupe</h2>${demands.length?`<div class="demand-list">${demands.map(([t,n])=>`<div><span>${esc(t)}</span><span class="demand-track"><span style="width:${Math.round(n/Math.max(1,participants.length)*100)}%"></span></span><strong>${n}</strong></div>`).join('')}</div>`:'<p>Aucun sujet demandé pour le moment.</p>'}<p class="muted">Les envies exprimées servent à choisir les usages concrets des ateliers.</p></div><div class="card"><h2>Préparer les prochains ateliers</h2><ol class="exercise"><li>Commencez par les prérequis qui nécessitent de l’aide : clavier, navigation, fichiers.</li><li>Choisissez ensuite les usages demandés par le groupe. Prévoyez une aide ciblée lorsque seuls quelques participants rencontrent une difficulté.</li><li>Complétez les observations manquantes avant de conclure. Reprenez quelques défis en fin de parcours pour rendre les progrès visibles.</li></ol><p class="muted">Les 12 ateliers restent à adapter. Aucun classement ni programme automatique à partir d’un score global.</p></div>`;
 document.querySelector('#summary-csv').onclick=()=>download('synthese-'+selected.code+'.csv',exportSummary(participants),'text/csv;charset=utf-8');
}
function prepareScreen(box){
 let elapsed=0;
 box.innerHTML=`<div class="card"><h2>La séance en 90 minutes</h2><p>Les durées sont des repères d’animation. Le participant peut passer une question et y revenir.</p><ol class="session-timeline">${stages.map(s=>{const from=elapsed;elapsed+=parseInt(s.minutes);return `<li><strong>${from}–${elapsed} min</strong><span>${s.title}</span></li>`;}).join('')}</ol></div><div class="card"><h2>Avant l’arrivée du groupe</h2><ol class="exercise"><li>Préparez un ordinateur, un navigateur et un éditeur de texte par personne. Seul l’exercice de recherche demande Internet en plus de la collecte.</li><li>Sur chaque bureau, créez le dossier <strong>Atelier</strong>. Placez-y les deux fichiers ci-dessous.</li><li>Essayez l’ouverture du fichier texte, le téléchargement et la sélection de pièce jointe. Le message d’exercice ne sera jamais envoyé.</li><li>Créez une séance, transmettez son code et expliquez que chacun peut demander de l’aide. Vous pouvez lire les consignes sans orienter les réponses.</li></ol><div class="actions"><a class="button secondary" href="./Depart.txt" download>Télécharger Depart.txt</a><a class="button secondary" href="./entrainement.html" download>Télécharger la page d’exercice</a></div></div><div class="card"><h2>Pendant et après la séance</h2><p>Observez les gestes dans les dossiers individuels. Si une personne répond à l’oral, notez-le dans ses situations. Les observations restent séparées de ses déclarations.</p><p>Avant de fermer la collecte, vérifiez les dernières transmissions et exportez les résultats. Sur un poste partagé, faites effacer la copie locale après récupération.</p></div>`;
}
function rating(name,value,labels=observationLabels){return `<select name="${name}" aria-label="${esc(name+' : observation de l’animateur')}">${Object.entries(labels).map(([v,label])=>`<option value="${v}" ${v===(value??'NO')?'selected':''}>${v} · ${label}</option>`).join('')}</select>`;}
function participant(id){
 detail=participants.find(p=>p.id===id);observationDirty=false;const p=detail;
 root.innerHTML=`<button id="back" class="secondary">Retour à la séance</button><p class="eyebrow">${esc(selected.title)}</p><h1>${esc(p.name)}</h1><p id="error" role="alert"></p><form id="observations"><div class="card"><div class="split"><h2>Observer les manipulations</h2><span id="obs-status" class="status" role="status"></span></div><p>Indiquez uniquement ce que vous avez observé. « Non observé » n’est pas un échec.</p>${content.challenges.map(c=>`<section class="observation-group"><h3>${c.id} · ${esc(c.title)}</h3><p><strong>Déclaration :</strong> ${esc(p.answers[c.id]??'Sans réponse')} ${p.answers[c.id+'_note']?'<br>'+esc(p.answers[c.id+'_note']):''}</p>${p.observations?.[c.id]?`<p class="muted">Ancienne observation globale : ${esc(p.observations[c.id])}. Elle reste conservée ; renseignez les gestes ci-dessous pour la synthèse détaillée.</p>`:''}<details><summary>Critère attendu</summary><p>${esc(c.success)}</p></details>${gestures.filter(g=>g.challenge===c.id).map(g=>`<div class="observation-row"><label for="obs-${g.id}">${esc(g.label)}</label>${rating(g.id,p.observations?.[g.id]).replace('<select','<select id="obs-'+g.id+'"')}</div>`).join('')}</section>`).join('')}</div><div class="card"><h2>Situations du quotidien</h2>${content.situations.map(s=>`<section class="observation-group"><h3>${s.id} · ${esc(s.title)}</h3><blockquote>${esc(p.answers[s.id]||'Sans réponse écrite. Une réponse orale peut être observée ci-dessous.')}</blockquote>${rating(s.id,p.observations?.[s.id],{NO:'Non observé',P:'Réponse pertinente',C:'À compléter',R:'Réflexe risqué'})}<details><summary>Repères de correction</summary><p>${esc(s.expected)}</p></details></section>`).join('')}<label for="note">Note de l’animateur et réponses orales</label><textarea id="note" name="note" maxlength="4000">${esc(p.observations?.note??'')}</textarea></div><div class="observation-save"><span id="dirty-status" role="status">Aucune modification en attente.</span><button>Enregistrer les observations</button></div></form><div class="card"><h2>Questions de connaissances</h2><div class="scroll"><table><thead><tr><th scope="col">Question</th><th scope="col">Réponse reçue</th><th scope="col">Résultat</th></tr></thead><tbody>${content.questions.map(q=>`<tr><th scope="row">${q.id} · ${esc(q.theme)}<details><summary>Question et correction</summary><p>${esc(q.q)}</p><p><strong>Réponse attendue :</strong> ${esc(q.options['ABCD'.indexOf(q.answer)])}</p><p>${esc(q.why)}</p></details></th><td>${esc(q.options['ABCD'.indexOf(p.answers[q.id])]??(p.answers[q.id]==='NSP'?'Je ne sais pas':p.answers[q.id])??'Sans réponse')}</td><td>${({J:'Juste',E:'À revoir',NSP:'Ne sait pas',NR:'Sans réponse'})[questionResult(q,p.answers[q.id])]}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>Habitudes et objectifs</h2>${Object.entries(p.answers).filter(([k])=>!content.questions.some(q=>q.id===k)&&!content.challenges.some(c=>c.id===k)&&!content.situations.some(s=>s.id===k)&&!k.startsWith('_')&&!/^D\d_note$/.test(k)).map(([k,v])=>`<p><strong>${esc(({devices:'Appareils',internet:'Internet à domicile',computer_ease:'Aisance déclarée sur ordinateur',mobile_ease:'Aisance déclarée sur smartphone',already:'Déjà autonome',help:'Besoin d’aide',interests:'Sujets demandés',other_interest:'Autre sujet',success:'Réussite',goal:'Objectif',D4_commune:'Commune',D4_horaire:'Horaire',D4_source:'Source'})[k]||k)}</strong><br>${esc(Array.isArray(v)?v.join(', '):v)}</p>`).join('')||'<p>Aucune information renseignée.</p>'}</div>`;
 document.querySelector('#back').onclick=()=>{if(!observationDirty||confirm('Quitter sans enregistrer les nouvelles observations ?'))dashboard();};
 document.querySelector('#observations').oninput=()=>{observationDirty=true;document.querySelector('#dirty-status').textContent='Modifications à enregistrer.';};
 document.querySelector('#observations').onsubmit=async e=>{
  e.preventDefault();const b=e.submitter;b.disabled=true;const observations={...p.observations,...Object.fromEntries(new FormData(e.target))};const fields=[...e.target.querySelectorAll('input,select,textarea')];fields.forEach(f=>f.disabled=true);const back=document.querySelector('#back');back.disabled=true;
  try{if(!demo)await rpc('save_observations',{p_participant:id,p_observations:observations},true);p.observations=observations;observationDirty=false;document.querySelector('#dirty-status').textContent=demo?'Modifié uniquement dans cette démonstration.':'Observations enregistrées.';document.querySelector('#obs-status').textContent='Enregistré';}catch(err){message(err);}finally{b.disabled=false;fields.forEach(f=>f.disabled=false);back.disabled=false;}
 };window.scrollTo(0,0);
}
window.addEventListener('beforeunload',e=>{if(observationDirty){e.preventDefault();e.returnValue='';}});
signIn();
